input.content:
/**
 * Shared utility type for an immutable branded identifier string.
 */
export type Id = string & {
  readonly __brand: 'Id';
};

/**
 * Shared utility type for an immutable branded slug string.
 */
export type Slug = string & {
  readonly __brand: 'Slug';
};

/**
 * Shared utility type for section anchor keys used by navigation and page sections.
 */
export type SectionKey = string & {
  readonly __brand: 'SectionKey';
};

/**
 * Shared utility type for ISO-8601 formatted date strings.
 */
export type ISODateString = string;

/**
 * Shared utility type for HTTP or HTTPS URLs represented as strings.
 */
export type UrlString = string;

/**
 * Shared utility type for CSS color values represented as strings.
 */
export type ColorValue = string;

/**
 * Shared utility type for arbitrary localized text content.
 */
export type LocalizedText = string;

/**
 * Describes a social profile or external link associated with an author.
 */
export interface SocialLink {
  /**
   * Provider name such as GitHub, X, LinkedIn, or Email.
   */
  readonly provider: string;

  /**
   * Human-readable label shown in the UI.
   */
  readonly label: string;

  /**
   * Destination URL or URI for the social profile.
   */
  readonly url: UrlString;

  /**
   * Optional icon identifier used by the design system.
   */
  readonly icon?: string;
}

/**
 * Represents the author or profile block displayed in the site header, about section, and post detail pages.
 */
export interface AuthorProfile {
  /**
   * Unique author identifier.
   */
  readonly id: Id;

  /**
   * SEO-friendly author slug.
   */
  readonly slug: Slug;

  /**
   * Display name of the author.
   */
  readonly name: string;

  /**
   * Short headline or title shown under the name.
   */
  readonly headline: string;

  /**
   * Longer biography used on the profile/about page.
   */
  readonly bio: string;

  /**
   * Optional short biography used in compact UI areas.
   */
  readonly summary?: string;

  /**
   * Avatar image URL.
   */
  readonly avatarUrl?: UrlString;

  /**
   * Banner or cover image URL for a richer profile presentation.
   */
  readonly coverImageUrl?: UrlString;

  /**
   * Primary role or profession, such as Frontend Engineer.
   */
  readonly role?: string;

  /**
   * Current location or timezone hint.
   */
  readonly location?: string;

  /**
   * Personal website or portfolio URL.
   */
  readonly websiteUrl?: UrlString;

  /**
   * Email address for contact or business inquiries.
   */
  readonly email?: string;

  /**
   * Social or external profile links.
   */
  readonly socialLinks: ReadonlyArray<SocialLink>;

  /**
   * Optional list of expertise tags displayed on the profile card.
   */
  readonly expertise?: ReadonlyArray<string>;
}

/**
 * Represents a top-level navigation entry or a nested submenu item.
 */
export interface NavigationItem {
  /**
   * Display label.
   */
  readonly label: string;

  /**
   * Navigation target URL.
   */
  readonly href: UrlString;

  /**
   * Optional named route to support client-side navigation.
   */
  readonly routeName?: BlogRouteName;

  /**
   * Optional section key for in-page anchor navigation.
   */
  readonly sectionKey?: SectionKey;

  /**
   * Indicates whether the navigation target is external.
   */
  readonly external?: boolean;

  /**
   * Marks the item as active in the current navigation context.
   */
  readonly active?: boolean;

  /**
   * Optional nested navigation items.
   */
  readonly children?: ReadonlyArray<NavigationItem>;
}

/**
 * Represents a call-to-action button displayed inside a hero section.
 */
export interface HeroAction {
  /**
   * Button label.
   */
  readonly label: string;

  /**
   * Target URL or route.
   */
  readonly href: UrlString;

  /**
   * Optional route name for app navigation.
   */
  readonly routeName?: BlogRouteName;

  /**
   * Optional visual emphasis style.
   */
  readonly variant?: 'primary' | 'secondary' | 'ghost';

  /**
   * Indicates whether this action opens in a new tab.
   */
  readonly external?: boolean;
}

/**
 * Represents a metric or highlight rendered within a hero section.
 */
export interface HeroStat {
  /**
   * Numeric or short textual value.
   */
  readonly value: string;

  /**
   * Meaningful label for the stat.
   */
  readonly label: string;

  /**
   * Optional supporting description.
   */
  readonly description?: string;
}

/**
 * Represents the content model for the homepage hero region.
 */
export interface HeroContent {
  /**
   * Primary hero title.
   */
  readonly title: string;

  /**
   * Optional subtitle or eyebrow text.
   */
  readonly eyebrow?: string;

  /**
   * Main supporting message below the title.
   */
  readonly description: string;

  /**
   * Optional highlighted keywords shown with visual emphasis.
   */
  readonly highlights?: ReadonlyArray<string>;

  /**
   * Optional primary action button.
   */
  readonly primaryAction?: HeroAction;

  /**
   * Optional secondary action button.
   */
  readonly secondaryAction?: HeroAction;

  /**
   * Optional image used in the hero area.
   */
  readonly imageUrl?: UrlString;

  /**
   * Optional accent or gradient token used by the design system.
   */
  readonly accent?: ColorValue;

  /**
   * Optional supporting statistics.
   */
  readonly stats?: ReadonlyArray<HeroStat>;
}

/**
 * Represents a blog category used for grouping and filtering posts.
 */
export interface BlogCategory {
  /**
   * Unique category identifier.
   */
  readonly id: Id;

  /**
   * Category slug.
   */
  readonly slug: Slug;

  /**
   * Display name.
   */
  readonly name: string;

  /**
   * Short description of the category.
   */
  readonly description?: string;

  /**
   * Optional category icon or symbol name.
   */
  readonly icon?: string;

  /**
   * Optional category accent color.
   */
  readonly color?: ColorValue;

  /**
   * Optional count of posts currently assigned to the category.
   */
  readonly postCount?: number;
}

/**
 * Represents a blog tag used for lightweight classification and filtering.
 */
export interface BlogTag {
  /**
   * Unique tag identifier.
   */
  readonly id: Id;

  /**
   * Tag slug.
   */
  readonly slug: Slug;

  /**
   * Display name.
   */
  readonly name: string;

  /**
   * Optional tag description.
   */
  readonly description?: string;

  /**
   * Optional accent color or badge color.
   */
  readonly color?: ColorValue;

  /**
   * Optional count of posts currently assigned to the tag.
   */
  readonly postCount?: number;
}

/**
 * Represents the lifecycle state of a blog post.
 */
export type BlogPostStatus = 'draft' | 'scheduled' | 'published' | 'archived';

/**
 * Represents SEO metadata used by pages and individual posts.
 */
export interface SeoMetadata {
  /**
   * SEO title.
   */
  readonly title?: string;

  /**
   * SEO description.
   */
  readonly description?: string;

  /**
   * Open Graph image URL.
   */
  readonly imageUrl?: UrlString;

  /**
   * Canonical URL for the page.
   */
  readonly canonicalUrl?: UrlString;

  /**
   * Keywords associated with the page.
   */
  readonly keywords?: ReadonlyArray<string>;
}

/**
 * Represents an image asset used in cards, posts, and hero sections.
 */
export interface ImageAsset {
  /**
   * Source URL.
   */
  readonly url: UrlString;

  /**
   * Alt text for accessibility.
   */
  readonly alt: string;

  /**
   * Optional width in pixels.
   */
  readonly width?: number;

  /**
   * Optional height in pixels.
   */
  readonly height?: number;

  /**
   * Optional focal point information used by the image component.
   */
  readonly focalPoint?: {
    readonly x: number;
    readonly y: number;
  };
}

/**
 * Represents a lightweight blog post shape suitable for list pages and cards.
 */
export interface BlogPostPreview {
  /**
   * Unique post identifier.
   */
  readonly id: Id;

  /**
   * Post slug.
   */
  readonly slug: Slug;

  /**
   * Post title.
   */
  readonly title: string;

  /**
   * Short excerpt shown in lists and cards.
   */
  readonly excerpt: string;

  /**
   * Optional cover image.
   */
  readonly coverImage?: ImageAsset;

  /**
   * Publication timestamp.
   */
  readonly publishedAt: ISODateString;

  /**
   * Optional time of last update.
   */
  readonly updatedAt?: ISODateString;

  /**
   * Estimated reading time in minutes.
   */
  readonly readingTimeMinutes: number;

  /**
   * Whether the post is highlighted as featured.
   */
  readonly featured?: boolean;

  /**
   * Primary category for the post.
   */
  readonly category?: BlogCategory;

  /**
   * Associated tags.
   */
  readonly tags: ReadonlyArray<BlogTag>;
}

/**
 * Represents the full blog post content and metadata used by the detail page.
 */
export interface BlogPost extends BlogPostPreview {
  /**
   * Full markdown or rich-text content.
   */
  readonly content: string;

  /**
   * Optional author of the post; defaults to the site author when omitted.
   */
  readonly author?: AuthorProfile;

  /**
   * Optional series or collection name.
   */
  readonly series?: string;

  /**
   * Optional canonical URL for this post.
   */
  readonly canonicalUrl?: UrlString;

  /**
   * Post publication state.
   */
  readonly status: BlogPostStatus;

  /**
   * Optional SEO metadata specific to the post.
   */
  readonly seo?: SeoMetadata;

  /**
   * Optional list of related post identifiers.
   */
  readonly relatedPostIds?: ReadonlyArray<Id>;

  /**
   * Optional table of contents headings used on the detail page.
   */
  readonly tableOfContents?: ReadonlyArray<TableOfContentsItem>;
}

/**
 * Represents a heading entry in a table of contents.
 */
export interface TableOfContentsItem {
  /**
   * Heading text.
   */
  readonly title: string;

  /**
   * Heading level between 1 and 6.
   */
  readonly level: 1 | 2 | 3 | 4 | 5 | 6;

  /**
   * Anchor ID used to jump to the heading.
   */
  readonly anchor: Slug;

  /**
   * Optional child headings for nested structures.
   */
  readonly children?: ReadonlyArray<TableOfContentsItem>;
}

/**
 * Represents route names used across the blog application.
 */
export type BlogRouteName =
  | 'home'
  | 'about'
  | 'blogIndex'
  | 'blogPostDetail'
  | 'categories'
  | 'categoryDetail'
  | 'tags'
  | 'tagDetail'
  | 'archive'
  | 'search';

/**
 * Represents a generic route parameter dictionary.
 */
export type RouteParams = Readonly<Record<string, string>>;

/**
 * Represents route parameters for each known blog route.
 */
export interface BlogRouteParamsByName {
  /** Route parameters for the home page. */
  readonly home: RouteParams;

  /** Route parameters for the about page. */
  readonly about: RouteParams;

  /** Route parameters for the blog index page. */
  readonly blogIndex: RouteParams;

  /** Route parameters for the blog post detail page. */
  readonly blogPostDetail: Readonly<{ slug: Slug }>;

  /** Route parameters for the categories overview page. */
  readonly categories: RouteParams;

  /** Route parameters for the category detail page. */
  readonly categoryDetail: Readonly<{ slug: Slug }>;

  /** Route parameters for the tags overview page. */
  readonly tags: RouteParams;

  /** Route parameters for the tag detail page. */
  readonly tagDetail: Readonly<{ slug: Slug }>;

  /** Route parameters for the archive page. */
  readonly archive: RouteParams;

  /** Route parameters for the search page. */
  readonly search: Readonly<{ query?: string }>;
}

/**
 * Describes a route definition with optional metadata for navigation, layout, and SEO.
 */
export interface RouteDefinition<
  TName extends BlogRouteName = BlogRouteName,
  TParams extends RouteParams = RouteParams,
> {
  /**
   * Unique route name.
   */
  readonly name: TName;

  /**
   * Route path pattern.
   */
  readonly path: string;

  /**
   * Optional route parameters.
   */
  readonly params?: TParams;

  /**
   * Human-readable title.
   */
  readonly title: string;

  /**
   * Optional description used for metadata and previews.
   */
  readonly description?: string;

  /**
   * Optional section key used to synchronize navigation state.
   */
  readonly sectionKey?: SectionKey;

  /**
   * Optional SEO metadata.
   */
  readonly seo?: SeoMetadata;

  /**
   * Indicates whether the route should be hidden from primary navigation.
   */
  readonly hidden?: boolean;
}

/**
 * Represents the full route map for the blog application.
 */
export type BlogRouteMap = {
  readonly [K in BlogRouteName]: RouteDefinition<K, BlogRouteParamsByName[K]>;
};

/**
 * Represents the smallest breakpoint name supported by the responsive layout system.
 */
export type ResponsiveBreakpointKey = 'xs' | 'sm' | 'md' | 'lg' | 'xl' | '2xl';

/**
 * Describes a responsive breakpoint and layout metadata for that viewport range.
 */
export interface ResponsiveBreakpoint {
  /**
   * Breakpoint key.
   */
  readonly key: ResponsiveBreakpointKey;

  /**
   * Minimum viewport width in pixels.
   */
  readonly minWidth: number;

  /**
   * Maximum viewport width in pixels.
   */
  readonly maxWidth?: number;

  /**
   * Recommended maximum content width for this breakpoint.
   */
  readonly containerMaxWidth?: number;

  /**
   * Recommended number of content columns.
   */
  readonly columns?: number;

  /**
   * Suggested horizontal gutter in pixels.
   */
  readonly gutter?: number;
}

/**
 * Represents a list of responsive breakpoints ordered from smallest to largest.
 */
export type ResponsiveBreakpointList = ReadonlyArray<ResponsiveBreakpoint>;

/**
 * Represents the responsive layout state exposed to components.
 */
export interface ResponsiveLayoutState {
  /**
   * Active breakpoint key.
   */
  readonly breakpoint: ResponsiveBreakpointKey;

  /**
   * Current viewport width.
   */
  readonly viewportWidth: number;

  /**
   * Current viewport height.
   */
  readonly viewportHeight: number;

  /**
   * Whether the viewport is considered mobile-sized.
   */
  readonly isMobile: boolean;

  /**
   * Whether the viewport is considered tablet-sized.
   */
  readonly isTablet: boolean;

  /**
   * Whether the viewport is considered desktop-sized.
   */
  readonly isDesktop: boolean;
}

/**
 * Represents a generic pagination state used by list pages.
 */
export interface PaginationState {
  /**
   * Current page number starting from 1.
   */
  readonly page: number;

  /**
   * Number of items shown per page.
   */
  readonly pageSize: number;

  /**
   * Total number of items available.
   */
  readonly totalItems: number;

  /**
   * Total number of pages available.
   */
  readonly totalPages: number;

  /**
   * Indicates whether a previous page exists.
   */
  readonly hasPreviousPage: boolean;

  /**
   * Indicates whether a next page exists.
   */
  readonly hasNextPage: boolean;

  /**
   * Previous page number when available.
   */
  readonly previousPage?: number;

  /**
   * Next page number when available.
   */
  readonly nextPage?: number;
}

/**
 * Represents a shared base shape for page view models.
 */
export interface BasePageViewModel {
  /**
   * Page title.
   */
  readonly title: string;

  /**
   * Optional page subtitle or description.
   */
  readonly description?: string;

  /**
   * Optional SEO metadata.
   */
  readonly seo?: SeoMetadata;

  /**
   * Optional active route name.
   */
  readonly activeRoute?: BlogRouteName;

  /**
   * Optional active section key.
   */
  readonly activeSection?: SectionKey;
}

/**
 * Represents layout-wide view model data shared by multiple pages.
 */
export interface LayoutViewModel {
  /**
   * Site author/profile.
   */
  readonly author: AuthorProfile;

  /**
   * Primary navigation items.
   */
  readonly navigation: ReadonlyArray<NavigationItem>;

  /**
   * Optional footer navigation items.
   */
  readonly footerNavigation?: ReadonlyArray<NavigationItem>;

  /**
   * Optional social links displayed in the footer or sidebar.
   */
  readonly socialLinks?: ReadonlyArray<SocialLink>;

  /**
   * Current responsive state.
   */
  readonly responsive: ResponsiveLayoutState;

  /**
   * Optional copyright notice.
   */
  readonly copyrightText?: string;

  /**
   * Optional theme mode currently active.
   */
  readonly themeMode?: 'light' | 'dark' | 'system';
}

/**
 * Represents the home page view model.
 */
export interface HomePageViewModel extends BasePageViewModel {
  /**
   * Hero content shown above the fold.
   */
  readonly hero: HeroContent;

  /**
   * Featured blog posts.
   */
  readonly featuredPosts: ReadonlyArray<BlogPostPreview>;

  /**
   * Latest or recent blog posts.
   */
  readonly recentPosts: ReadonlyArray<BlogPostPreview>;

  /**
   * Categories highlighted on the home page.
   */
  readonly categories: ReadonlyArray<BlogCategory>;

  /**
   * Popular or highlighted tags.
   */
  readonly tags: ReadonlyArray<BlogTag>;

  /**
   * Optional author profile summary card.
   */
  readonly profile?: AuthorProfile;

  /**
   * Optional homepage statistics.
   */
  readonly stats?: ReadonlyArray<HeroStat>;
}

/**
 * Represents the blog listing page view model.
 */
export interface BlogIndexPageViewModel extends BasePageViewModel {
  /**
   * Blog posts shown on the current page.
   */
  readonly posts: ReadonlyArray<BlogPostPreview>;

  /**
   * Pagination information.
   */
  readonly pagination: PaginationState;

  /**
   * Categories used for filtering.
   */
  readonly categories: ReadonlyArray<BlogCategory>;

  /**
   * Tags used for filtering.
   */
  readonly tags: ReadonlyArray<BlogTag>;

  /**
   * Currently active category slug filter, if any.
   */
  readonly activeCategorySlug?: Slug;

  /**
   * Currently active tag slug filter, if any.
   */
  readonly activeTagSlug?: Slug;

  /**
   * Search query applied to the listing, if any.
   */
  readonly searchQuery?: string;
}

/**
 * Represents the blog post detail page view model.
 */
export interface BlogPostDetailPageViewModel extends BasePageViewModel {
  /**
   * Current blog post.
   */
  readonly post: BlogPost;

  /**
   * Author associated with the current post.
   */
  readonly author: AuthorProfile;

  /**
   * Related posts displayed below the article.
   */
  readonly relatedPosts: ReadonlyArray<BlogPostPreview>;

  /**
   * Previous post in chronological or contextual order.
   */
  readonly previousPost?: BlogPostPreview;

  /**
   * Next post in chronological or contextual order.
   */
  readonly nextPost?: BlogPostPreview;

  /**
   * Breadcrumb trail for the detail page.
   */
  readonly breadcrumbs: ReadonlyArray<BreadcrumbItem>;
}

/**
 * Represents a breadcrumb item used for navigation and schema-friendly UI.
 */
export interface BreadcrumbItem {
  /**
   * Display label.
   */
  readonly label: string;

  /**
   * Destination URL.
   */
  readonly href: UrlString;

  /**
   * Optional route name.
   */
  readonly routeName?: BlogRouteName;
}

/**
 * Represents the category detail page view model.
 */
export interface CategoryPageViewModel extends BasePageViewModel {
  /**
   * The selected category.
   */
  readonly category: BlogCategory;

  /**
   * Posts assigned to the selected category.
   */
  readonly posts: ReadonlyArray<BlogPostPreview>;

  /**
   * Pagination information for the category posts.
   */
  readonly pagination: PaginationState;

  /**
   * All available categories.
   */
  readonly categories: ReadonlyArray<BlogCategory>;
}

/**
 * Represents the tag detail page view model.
 */
export interface TagPageViewModel extends BasePageViewModel {
  /**
   * The selected tag.
   */
  readonly tag: BlogTag;

  /**
   * Posts assigned to the selected tag.
   */
  readonly posts: ReadonlyArray<BlogPostPreview>;

  /**
   * Pagination information for the tag posts.
   */
  readonly pagination: PaginationState;

  /**
   * All available tags.
   */
  readonly tags: ReadonlyArray<BlogTag>;
}

/**
 * Represents the archive page view model.
 */
export interface ArchivePageViewModel extends BasePageViewModel {
  /**
   * All posts available in the archive.
   */
  readonly posts: ReadonlyArray<BlogPostPreview>;

  /**
   * Available years grouped for archive navigation.
   */
  readonly years: ReadonlyArray<number>;

  /**
   * Pagination information for archive browsing.
   */
  readonly pagination: PaginationState;
}

/**
 * Represents the search results page view model.
 */
export interface SearchResultsPageViewModel extends BasePageViewModel {
  /**
   * Search term entered by the user.
   */
  readonly query: string;

  /**
   * Matching blog posts.
   */
  readonly results: ReadonlyArray<BlogPostPreview>;

  /**
   * Pagination information for search results.
   */
  readonly pagination: PaginationState;

  /**
   * Categories that can be used to narrow search results.
   */
  readonly categories: ReadonlyArray<BlogCategory>;

  /**
   * Tags that can be used to narrow search results.
   */
  readonly tags: ReadonlyArray<BlogTag>;
}

/**
 * Represents a reusable content section item for modern long-form layouts.
 */
export interface SectionContentItem {
  /**
   * Stable section key.
   */
  readonly key: SectionKey;

  /**
   * Display title.
   */
  readonly title: string;

  /**
   * Optional subtitle.
   */
  readonly subtitle?: string;

  /**
   * Optional section description.
   */
  readonly description?: string;

  /**
   * Optional anchor id used for deep linking.
   */
  readonly anchor?: Slug;
}

/**
 * Represents a reusable filter state for category/tag/search-based content lists.
 */
export interface ContentFilterState {
  /**
   * Selected category slug.
   */
  readonly categorySlug?: Slug;

  /**
   * Selected tag slug.
   */
  readonly tagSlug?: Slug;

  /**
   * Text query used for keyword search.
   */
  readonly query?: string;

  /**
   * Whether featured content only should be shown.
   */
  readonly featuredOnly?: boolean;
}

/**
 * Represents the common site data bundle used to hydrate pages.
 */
export interface SiteDataModel {
  /**
   * Core layout model.
   */
  readonly layout: LayoutViewModel;

  /**
   * Shared navigation routes.
   */
  readonly routes: BlogRouteMap;

  /**
   * All responsive breakpoint metadata.
   */
  readonly breakpoints: ResponsiveBreakpointList;

  /**
   * Site-wide categories.
   */
  readonly categories: ReadonlyArray<BlogCategory>;

  /**
   * Site-wide tags.
   */
  readonly tags: ReadonlyArray<BlogTag>;

  /**
   * Site-wide author profile.
   */
  readonly author: AuthorProfile;
}

// Static content dataset for the personal blog.

/** Author profile information. */
export interface AuthorProfile {
  /** Display name of the author. */
  name: string;
  /** Short professional headline. */
  headline: string;
  /** Short biography. */
  bio: string;
  /** Primary location or timezone note. */
  location: string;
  /** Social or contact links. */
  links: ReadonlyArray<ProfileLink>;
}

/** A profile link displayed in the UI. */
export interface ProfileLink {
  /** Human-readable label. */
  label: string;
  /** URL target. */
  href: string;
}

/** Hero section copy for the blog landing page. */
export interface HeroCopy {
  /** Headline shown above the fold. */
  title: string;
  /** Supporting description shown under the title. */
  subtitle: string;
  /** Call to action label. */
  primaryCtaLabel: string;
  /** Call to action destination. */
  primaryCtaHref: string;
  /** Secondary call to action label. */
  secondaryCtaLabel: string;
  /** Secondary call to action destination. */
  secondaryCtaHref: string;
}

/** Navigation entry used by layout rendering. */
export interface NavigationEntry {
  /** Label shown in the navigation menu. */
  label: string;
  /** Route path for the navigation entry. */
  href: string;
}

/** Category metadata for grouping posts. */
export interface Category {
  /** URL-safe category slug. */
  slug: string;
  /** Display name. */
  name: string;
  /** Short description. */
  description: string;
}

/** Tag metadata for grouping posts. */
export interface Tag {
  /** URL-safe tag slug. */
  slug: string;
  /** Display name. */
  name: string;
}

/** Curated blog post content. */
export interface BlogPost {
  /** URL-safe article slug. */
  slug: string;
  /** Article title. */
  title: string;
  /** Short summary used in list pages and previews. */
  summary: string;
  /** Cover image reference or path. */
  coverImage: string;
  /** Published date in ISO 8601 format. */
  publishedAt: string;
  /** Estimated reading time in minutes. */
  readingTimeMinutes: number;
  /** Category slug. */
  categorySlug: string;
  /** Tag slugs associated with the post. */
  tagSlugs: ReadonlyArray<string>;
  /** Full article body. */
  body: string;
}

