    { label: "X", href: "https://x.com/liu_an" },
    { label: "Email", href: "mailto:hello@example.com" },
  ],
};

/** Landing page hero copy. */
export const heroCopy: HeroCopy = {
  title: "Ideas for building calm, useful software.",
  subtitle:
    "Notes on frontend systems, product craft, and the small decisions that make interfaces feel effortless.",
  primaryCtaLabel: "Read latest posts",
  primaryCtaHref: "/blog",
  secondaryCtaLabel: "About the author",
  secondaryCtaHref: "/about",
