import type { AuthorProfile, ProfileLink } from './data';

/** Route kinds supported by the application. */
export type RouteName = 'home' | 'post' | 'category' | 'tag' | 'about' | 'profile' | 'not-found';

/** Normalized route state used by the app shell. */
export interface RouteState {
  /** Route kind. */
  readonly name: RouteName;
  /** Optional post slug. */
  readonly slug: string | null;
  /** Optional category slug. */
  readonly category: string | null;
  /** Optional tag slug. */
  readonly tag: string | null;
  /** Original hash value, normalized without the leading #. */
  readonly hash: string;
}

/** Listener callback invoked when the route changes. */
export type RouteChangeListener = (route: RouteState) => void;

/** Serializable navigation target used for formatting hashes. */
export interface RouteTarget {
  /** Target route name. */
  readonly name: RouteName;
  /** Optional post slug. */
  readonly slug?: string | null;
  /** Optional category slug. */
  readonly category?: string | null;
  /** Optional tag slug. */
  readonly tag?: string | null;
}

const HOME_HASH = '';
const ABOUT_HASH = 'about';
const PROFILE_HASH = 'profile';
const POSTS_PREFIX = 'post/';
const CATEGORY_PREFIX = 'category/';
const TAG_PREFIX = 'tag/';

const listeners: Set<RouteChangeListener> = new Set<RouteChangeListener>();
let currentRoute: RouteState = parseRouteFromHash(readCurrentHash());
let initialized = false;

function readCurrentHash(): string {
  if (typeof window === 'undefined' || typeof window.location === 'undefined') {
    return '';
  }
  return window.location.hash;
}

function stripLeadingHash(hash: string): string {
  return hash.startsWith('#') ? hash.slice(1) : hash;
}

function trimSlashes(value: string): string {
  return value.replace(/^\/+|\/+$/g, '');
}

function normalizeSegment(value: string): string {
  return decodeURIComponent(trimSlashes(value.trim()));
}

function encodeSegment(value: string): string {
  return encodeURIComponent(trimSlashes(value.trim()));
}

function buildRouteState(name: RouteName, hash: string, extras?: Partial<RouteState>): RouteState {
  return {
    name,
    slug: extras?.slug ?? null,
    category: extras?.category ?? null,
    tag: extras?.tag ?? null,
    hash,
  };
}

/** Parse a hash string into a normalized route state. */
export function parseRouteFromHash(hash: string | null | undefined): RouteState {
  const normalizedHash: string = stripLeadingHash((hash ?? '').trim());
  const path: string = trimSlashes(normalizedHash);

  if (path === '' || path === HOME_HASH) {
    return buildRouteState('home', '');
  }

  if (path === ABOUT_HASH || path === PROFILE_HASH) {
    return buildRouteState(path === ABOUT_HASH ? 'about' : 'profile', path);
  }

  if (path.startsWith(POSTS_PREFIX)) {
    const slugValue: string = normalizeSegment(path.slice(POSTS_PREFIX.length));
    if (slugValue === '') {
      return buildRouteState('not-found', path);
    }
    return buildRouteState('post', path, { slug: slugValue });
  }

  if (path.startsWith(CATEGORY_PREFIX)) {
    const categoryValue: string = normalizeSegment(path.slice(CATEGORY_PREFIX.length));
    if (categoryValue === '') {
      return buildRouteState('not-found', path);
    }
    return buildRouteState('category', path, { category: categoryValue });
  }

  if (path.startsWith(TAG_PREFIX)) {
    const tagValue: string = normalizeSegment(path.slice(TAG_PREFIX.length));
    if (tagValue === '') {
      return buildRouteState('not-found', path);
    }
    return buildRouteState('tag', path, { tag: tagValue });
  }

  return buildRouteState('not-found', path);
}

/** Format a route target into a hash string suitable for client-side navigation. */
export function formatRouteHash(target: RouteTarget): string {
  switch (target.name) {
    case 'home':
      return '#';
    case 'about':
      return '#about';
    case 'profile':
      return '#profile';
    case 'post': {
      const slugValue: string = typeof target.slug === 'string' ? target.slug : '';
      return slugValue.trim() === '' ? '#' : `#${POSTS_PREFIX}${encodeSegment(slugValue)}`;
    }
    case 'category': {
      const categoryValue: string = typeof target.category === 'string' ? target.category : '';
      return categoryValue.trim() === '' ? '#' : `#${CATEGORY_PREFIX}${encodeSegment(categoryValue)}`;
    }
    case 'tag': {
      const tagValue: string = typeof target.tag === 'string' ? target.tag : '';
      return tagValue.trim() === '' ? '#' : `#${TAG_PREFIX}${encodeSegment(tagValue)}`;
    }
    case 'not-found':
    default:
      return `#${stripLeadingHash(currentRoute.hash)}`;
  }
}

/** Get the current route state. */
export function getCurrentRoute(): RouteState {
  return currentRoute;
}

/** Check whether the provided route name is currently active. */
export function isActiveRoute(name: RouteName): boolean {
  return currentRoute.name === name;
}

/** Register a callback that runs whenever the route changes. */
export function onRouteChange(listener: RouteChangeListener): () => void {
  listeners.add(listener);
  return (): void => {
    listeners.delete(listener);
  };
}

function emitRouteChange(route: RouteState): void {
  listeners.forEach((listener: RouteChangeListener): void => {
    listener(route);
  });
}

function syncFromLocation(): void {
  const nextRoute: RouteState = parseRouteFromHash(readCurrentHash());
  currentRoute = nextRoute;
  emitRouteChange(nextRoute);
}

/** Initialize hash routing and subscribe to browser navigation events. */
export function initializeRouter(): void {
  if (initialized || typeof window === 'undefined') {
    initialized = true;
    return;
  }

  initialized = true;
  currentRoute = parseRouteFromHash(readCurrentHash());
  window.addEventListener('hashchange', syncFromLocation);
  emitRouteChange(currentRoute);
}

/** Navigate to a route without reloading the page. */
export function navigate(target: RouteTarget): void {
  const nextHash: string = formatRouteHash(target);
  if (typeof window === 'undefined' || typeof window.location === 'undefined') {
    currentRoute = parseRouteFromHash(nextHash);
    emitRouteChange(currentRoute);
    return;
  }

  const nextValue: string = stripLeadingHash(nextHash);
  if (stripLeadingHash(window.location.hash) === nextValue) {
    return;
  }
  window.location.hash = nextValue;
}

/** Build a home route target. */
export function homeRoute(): RouteTarget {
  return { name: 'home' };
}

/** Build a post detail route target. */
export function postRoute(slug: string): RouteTarget {
  return { name: 'post', slug };
}

/** Build a category listing route target. */
export function categoryRoute(category: string): RouteTarget {
  return { name: 'category', category };
}

/** Build a tag listing route target. */
export function tagRoute(tag: string): RouteTarget {
  return { name: 'tag', tag };
}

/** Build an about/profile route target. */
export function aboutRoute(): RouteTarget {
  return { name: 'about' };
}

/** Build a profile route target. */
export function profileRoute(): RouteTarget {
  return { name: 'profile' };
}

/** Type guard for post detail routes. */
export function isPostRoute(route: RouteState): route is RouteState & { readonly slug: string } {
  return route.name === 'post' && typeof route.slug === 'string';
}

/** Type guard for category routes. */
export function isCategoryRoute(route: RouteState): route is RouteState & { readonly category: string } {
  return route.name === 'category' && typeof route.category === 'string';
}

/** Type guard for tag routes. */
export function isTagRoute(route: RouteState): route is RouteState & { readonly tag: string } {
  return route.name === 'tag' && typeof route.tag === 'string';
}

/** Resolve a human-readable title for a route, useful for shells and headers. */
export function getRouteTitle(route: RouteState, profile?: AuthorProfile): string {
  switch (route.name) {
    case 'home':
      return profile?.name ?? 'Home';
    case 'post':
      return route.slug ?? 'Post';
    case 'category':
      return route.category ? `Category: ${route.category}` : 'Category';
    case 'tag':
      return route.tag ? `Tag: ${route.tag}` : 'Tag';
    case 'about':
    case 'profile':
      return profile?.headline ?? 'About';
    default:
      return 'Not Found';
  }
}

/** Get a normalized array of profile links, guarding against nullish inputs. */
export function normalizeProfileLinks(links: ReadonlyArray<ProfileLink> | null | undefined): ReadonlyArray<ProfileLink> {
  return Array.isArray(links) ? links.filter((link: ProfileLink): boolean => link.label.trim() !== '' && link.href.trim() !== '') : [];
}

