import type {
  AuthorProfile,
  BlogPost,
  Category,
  HeroCopy,
  NavigationEntry,
  Tag,
} from "./data";

/** A minimal mapping of HTML tag names to their created elements. */
export type ElementTagNameMap = HTMLElementTagNameMap & SVGElementTagNameMap;

/** Children values accepted by the DOM creation helpers. */
export type ChildValue = Node | string | number | boolean | null | undefined;

/** Props accepted by the generic element creation helper. */
export interface ElementProps {
  /** Element id attribute. */
  id?: string;
  /** Element class names. */
  className?: string;
  /** Data attributes to apply. */
  dataset?: Readonly<Record<string, string>>;
  /** Element attributes to apply. */
  attrs?: Readonly<Record<string, string | number | boolean | null | undefined>>;
  /** Inline style properties to apply. */
  style?: Readonly<Record<string, string | number | null | undefined>>;
  /** Event listeners to attach. */
  on?: Readonly<Record<string, EventListenerOrEventListenerObject>>;
  /** Element role attribute. */
  role?: string;
  /** Element tab index. */
  tabIndex?: number;
  /** Text content to set. */
  textContent?: string;
  /** Children to append. */
  children?: ReadonlyArray<ChildValue>;
}

/** A typed section layout description. */
export interface SectionLayoutSpec {
  /** Root section label for assistive technology. */
  ariaLabel?: string;
  /** Title to render in the section header. */
  title?: string;
  /** Supporting description in the section header. */
  description?: string;
  /** Content nodes for the section body. */
  children: ReadonlyArray<ChildValue>;
}

/** A blog article view model for rendering a post detail page. */
export interface ArticleDetailModel {
  /** The article being rendered. */
  post: BlogPost;
  /** Optional category metadata. */
  category?: Category | null;
  /** Optional tag metadata for the article. */
  tags?: ReadonlyArray<Tag>;
}

/** Escape HTML special characters in text content. */
export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** Create a DOM element with typed props and children. */
export function createElement<K extends keyof ElementTagNameMap>(
  tagName: K,
  props: ElementProps = {},
  ...children: ChildValue[]
): ElementTagNameMap[K] {
  const element: ElementTagNameMap[K] = document.createElement(tagName as string) as ElementTagNameMap[K];
  applyProps(element, props);
  appendChildren(element, children.length > 0 ? children : props.children ?? []);
  return element;
}

/** Create a text node from arbitrary content. */
export function createText(value: string | number | boolean | null | undefined): Text {
  return document.createTextNode(value == null ? "" : String(value));
}

/** Remove all child nodes from a container. */
export function clearElement(element: Element): void {
  while (element.firstChild !== null) {
    element.removeChild(element.firstChild);
  }
}

/** Update a container by clearing and mounting fresh content. */
export function updateElement(container: Element, content: ChildValue | ReadonlyArray<ChildValue>): void {
  clearElement(container);
  appendChildren(container, Array.isArray(content) ? content : [content]);
}

/** Render the navigation bar. */
export function mountNavigationBar(entries: ReadonlyArray<NavigationEntry>): HTMLElement {
  const navList = createElement(
    "ul",
    { className: "nav__list" },
    ...entries.map((entry) =>
      createElement(
        "li",
        { className: "nav__item" },
        createElement("a", { className: "nav__link", attrs: { href: entry.href } }, entry.label),
      ),
    ),
  );

  return createElement(
    "nav",
    { className: "nav", role: "navigation", attrs: { "aria-label": "Primary" } },
    createElement("div", { className: "nav__brand" }, createElement("span", { className: "nav__logo", textContent: "★" }), createElement("span", { className: "nav__title", textContent: "Blog" })),
    navList,
  );
}

/** Render the hero section. */
export function mountHeroSection(hero: HeroCopy): HTMLElement {
  return createElement(
    "section",
    { className: "hero", attrs: { "aria-labelledby": "hero-title" } },
    createElement(
      "div",
      { className: "hero__content" },
      createElement("p", { className: "hero__eyebrow", textContent: "Personal blog" }),
      createElement("h1", { id: "hero-title", className: "hero__title", textContent: hero.title }),
      createElement("p", { className: "hero__subtitle", textContent: hero.subtitle }),
      createElement(
        "div",
        { className: "hero__actions" },
        createElement("a", { className: "button button--primary", attrs: { href: hero.primaryCtaHref } }, hero.primaryCtaLabel),
        createElement("a", { className: "button button--secondary", attrs: { href: hero.secondaryCtaHref } }, hero.secondaryCtaLabel),
      ),
    ),
  );
}

/** Render a profile card. */
export function mountProfileCard(profile: AuthorProfile): HTMLElement {
  return createElement(
    "aside",
    { className: "profile-card" },
    createElement("h2", { className: "profile-card__name", textContent: profile.name }),
    createElement("p", { className: "profile-card__headline", textContent: profile.headline }),
    createElement("p", { className: "profile-card__bio", textContent: profile.bio }),
    createElement("p", { className: "profile-card__location", textContent: profile.location }),
    createElement(
      "div",
      { className: "profile-card__links" },
      ...profile.links.map((link) => createElement("a", { className: "chip chip--link", attrs: { href: link.href } }, link.label)),
    ),
  );
}

/** Render a category or tag chip. */
export function mountChip(label: string, href?: string): HTMLElement {
  return href
    ? createElement("a", { className: "chip", attrs: { href } }, label)
    : createElement("span", { className: "chip", textContent: label });
}

/** Render a post preview card. */
export function mountPostCard(post: BlogPost, categoryName?: string, tagNames?: ReadonlyArray<string>): HTMLElement {
  return createElement(
    "article",
    { className: "post-card" },
    createElement("a", { className: "post-card__cover", attrs: { href: `/posts/${post.slug}` } }, createElement("img", { attrs: { src: post.coverImage, alt: post.title, loading: "lazy" } })),
    createElement(
      "div",
      { className: "post-card__body" },
      categoryName ? mountChip(categoryName) : createElement("span", { className: "post-card__meta", textContent: "Article" }),
      createElement("h3", { className: "post-card__title" }, createElement("a", { attrs: { href: `/posts/${post.slug}` } }, post.title)),
      createElement("p", { className: "post-card__summary", textContent: post.summary }),
      createElement("div", { className: "post-card__footer" }, createElement("time", { attrs: { datetime: post.publishedAt }, textContent: post.publishedAt }), createElement("span", { textContent: `${post.readingTimeMinutes} min read` })),
      tagNames && tagNames.length > 0 ? createElement("div", { className: "post-card__tags" }, ...tagNames.map((tag) => mountChip(tag))) : createElement("span", { className: "post-card__tags post-card__tags--empty" }),
    ),
  );
}

/** Render an article detail view. */
export function mountArticleDetailView(model: ArticleDetailModel): HTMLElement {
  const tagChips: ReadonlyArray<HTMLElement> = model.tags ? model.tags.map((tag) => mountChip(tag.name)) : [];
  return createElement(
    "article",
    { className: "article-detail" },
    createElement("header", { className: "article-detail__header" }, createElement("h1", { className: "article-detail__title", textContent: model.post.title }), createElement("p", { className: "article-detail__summary", textContent: model.post.summary })),
    createElement("div", { className: "article-detail__meta" }, model.category ? mountChip(model.category.name) : createElement("span", { className: "chip", textContent: "Uncategorized" }), createElement("time", { attrs: { datetime: model.post.publishedAt }, textContent: model.post.publishedAt }), createElement("span", { textContent: `${model.post.readingTimeMinutes} min read` })),
    createElement("img", { className: "article-detail__cover", attrs: { src: model.post.coverImage, alt: model.post.title } }),
    createElement("div", { className: "article-detail__body" }, createElement("p", { textContent: model.post.body })),
    tagChips.length > 0 ? createElement("footer", { className: "article-detail__tags" }, ...tagChips) : createElement("footer", { className: "article-detail__tags article-detail__tags--empty" }),
  );
}

/** Render a responsive section layout wrapper. */
export function mountResponsiveSectionLayout(spec: SectionLayoutSpec): HTMLElement {
  return createElement(
    "section",
    { className: "responsive-section", attrs: spec.ariaLabel ? { "aria-label": spec.ariaLabel } : undefined },
