import type {
  AuthorProfile,
  BlogPost,
  Category,
  HeroCopy,
  NavigationEntry,
  Tag,
} from './data';
import {
  authorProfile,
  categories,
  heroCopy,
  navigationEntries,
  posts as blogPosts,
  tags,
} from './data';
import type { RouteName, RouteState, RouteTarget } from './router';
import { formatRouteHash, parseRouteFromHash } from './router';
import {
  clearElement,
  createElement,
  createText,
  type ChildValue,
  type ElementProps,
} from './render';

/** A composed page view model for rendering a route. */
export interface PageViewModel {
  /** Page title. */
  readonly title: string;
  /** Meta description. */
  readonly description: string;
  /** Main hero content. */
  readonly hero?: HeroViewModel | null;
  /** Featured posts to highlight. */
  readonly featuredPosts: ReadonlyArray<PostCardViewModel>;
  /** Primary list of posts. */
  readonly posts: ReadonlyArray<PostCardViewModel>;
  /** Optional detail article. */
  readonly article?: ArticleViewModel | null;
  /** Optional sidebar panels. */
  readonly sidebarPanels: ReadonlyArray<SidebarPanelViewModel>;
  /** Optional profile/about section. */
  readonly profile?: ProfileViewModel | null;
  /** Optional empty state message. */
  readonly emptyState?: EmptyStateViewModel | null;
}

/** Hero section view model. */
export interface HeroViewModel {
  /** Hero title. */
  readonly title: string;
  /** Hero subtitle. */
  readonly subtitle: string;
  /** Primary CTA label. */
  readonly primaryCtaLabel: string;
  /** Primary CTA target. */
  readonly primaryCtaHref: string;
  /** Secondary CTA label. */
  readonly secondaryCtaLabel: string;
  /** Secondary CTA target. */
  readonly secondaryCtaHref: string;
}

/** Post card view model. */
export interface PostCardViewModel {
  /** Post slug. */
  readonly slug: string;
  /** Post title. */
  readonly title: string;
  /** Post summary. */
  readonly summary: string;
  /** Published date label. */
  readonly publishedLabel: string;
  /** Reading time label. */
  readonly readingTimeLabel: string;
  /** Category label. */
  readonly categoryLabel: string;
  /** Post href. */
  readonly href: string;
}

/** Article detail view model. */
export interface ArticleViewModel {
  /** Post title. */
  readonly title: string;
  /** Post body. */
  readonly body: string;
  /** Meta labels. */
  readonly meta: ReadonlyArray<string>;
  /** Post href. */
  readonly href: string;
}

/** Sidebar panel view model. */
export interface SidebarPanelViewModel {
  /** Panel title. */
  readonly title: string;
  /** Panel items. */
  readonly items: ReadonlyArray<SidebarItemViewModel>;
}

/** Sidebar item view model. */
export interface SidebarItemViewModel {
  /** Item label. */
  readonly label: string;
  /** Item href. */
  readonly href?: string | null;
  /** Item supporting text. */
  readonly description?: string | null;
}

/** Profile/about section view model. */
export interface ProfileViewModel {
  /** Author profile. */
  readonly profile: AuthorProfile;
}

/** Empty state view model. */
export interface EmptyStateViewModel {
  /** Empty state title. */
  readonly title: string;
  /** Empty state description. */
  readonly description: string;
  /** Suggested route label. */
  readonly ctaLabel: string;
  /** Suggested route target. */
  readonly ctaHref: string;
}

interface IndexedPost extends BlogPost {
  readonly categoryName: string;
  readonly tagNames: ReadonlyArray<string>;
}

const posts: ReadonlyArray<IndexedPost> = blogPosts.map((post: BlogPost) => ({
  ...post,
  categoryName: getCategory(post.categorySlug)?.name ?? post.categorySlug,
  tagNames: post.tagSlugs.map((slug: string) => getTag(slug)?.name ?? slug),
}));

/** Build a page model from the current route state. */
export function buildPageViewModel(route: RouteState): PageViewModel {
  switch (route.name) {
    case 'home':
      return buildHomePageModel();
    case 'post':
      return buildPostPageModel(route.slug);
    case 'category':
      return buildCategoryPageModel(route.category);
    case 'tag':
      return buildTagPageModel(route.tag);
    case 'about':
    case 'profile':
      return buildProfilePageModel(route.name);
    default:
      return buildNotFoundPageModel();
  }
}

/** Render the current route into the given root element. */
export function renderPage(root: Element, route: RouteState): PageViewModel {
  const viewModel: PageViewModel = buildPageViewModel(route);
  clearElement(root);
  root.appendChild(renderPageElement(viewModel));
  updateDocumentMetadata(viewModel.title, viewModel.description);
  return viewModel;
}

/** Initialize page rendering for hash-based navigation. */
export function initializePages(root: Element): void {
  const renderCurrent = (): void => {
    renderPage(root, parseRouteFromHash(readHash()));
  };
  renderCurrent();
  if (typeof window !== 'undefined') {
    window.addEventListener('hashchange', renderCurrent);
  }
}

function readHash(): string {
  return typeof window === 'undefined' ? '' : window.location.hash;
}

function updateDocumentMetadata(title: string, description: string): void {
  if (typeof document === 'undefined') {
    return;
  }
  document.title = title;
  let metaDescription: HTMLMetaElement | null = document.querySelector('meta[name="description"]');
  if (metaDescription === null) {
    metaDescription = document.createElement('meta');
    metaDescription.setAttribute('name', 'description');
    document.head.appendChild(metaDescription);
  }
  metaDescription.setAttribute('content', description);
}

function buildHomePageModel(): PageViewModel {
  const featuredPosts: ReadonlyArray<PostCardViewModel> = posts.slice(0, 3).map(toPostCardModel);
  return {
    title: `${heroCopy.title} | ${authorProfile.name}`,
    description: heroCopy.subtitle,
    hero: toHeroModel(heroCopy),
    featuredPosts,
    posts: posts.map(toPostCardModel),
    sidebarPanels: [toNavigationPanel(), toCategoryPanel(), toTagPanel()],
    profile: null,
    emptyState: null,
  };
}

function buildPostPageModel(slug: string | null): PageViewModel {
  const post: IndexedPost | undefined = findPostBySlug(slug);
  if (post === undefined) {
    return buildNotFoundPageModel();
  }
  const category: Category | null = getCategory(post.categorySlug);
  const tagModels: ReadonlyArray<Tag> = post.tagSlugs.map((tagSlug: string) => getTag(tagSlug)).filter((tag: Tag | null): tag is Tag => tag !== null);
  return {
    title: `${post.title} | ${authorProfile.name}`,
    description: post.summary,
    hero: null,
    featuredPosts: [],
    posts: relatedPosts(post.slug).map(toPostCardModel),
    article: {
      title: post.title,
      body: post.body,
      meta: [post.publishedAt, `${post.readingTimeMinutes} min read`, category?.name ?? post.categorySlug, ...tagModels.map((tag: Tag) => tag.name)],
      href: createRouteHref({ name: 'post', slug: post.slug }),
    },
    sidebarPanels: [toArticleSidebarPanel(post), toNavigationPanel()],
    profile: null,
    emptyState: null,
  };
}

function buildCategoryPageModel(categorySlug: string | null): PageViewModel {
  const category: Category | null = categorySlug === null ? null : getCategory(categorySlug);
  const matchingPosts: ReadonlyArray<PostCardViewModel> = posts.filter((post: IndexedPost) => post.categorySlug === categorySlug).map(toPostCardModel);
  if (category === null) {
    return buildNotFoundPageModel();
  }
  return {
    title: `${category.name} | ${authorProfile.name}`,
    description: category.description,
    hero: null,
    featuredPosts: matchingPosts.slice(0, 2),
    posts: matchingPosts,
    sidebarPanels: [toCategoryPanel(), toNavigationPanel()],
    profile: null,
    emptyState: matchingPosts.length === 0 ? toEmptyState('No posts in this category yet.', 'Explore all posts', '#') : null,
  };
}

function buildTagPageModel(tagSlug: string | null): PageViewModel {
  const tag: Tag | null = tagSlug === null ? null : getTag(tagSlug);
  if (tag === null) {
    return buildNotFoundPageModel();
  }
  const matchingPosts: ReadonlyArray<PostCardViewModel> = posts.filter((post: IndexedPost) => post.tagSlugs.includes(tag.slug)).map(toPostCardModel);
  return {
    title: `#${tag.name} | ${authorProfile.name}`,
    description: `Posts tagged with ${tag.name}.`,
    hero: null,
    featuredPosts: matchingPosts.slice(0, 2),
    posts: matchingPosts,
    sidebarPanels: [toTagPanel(), toNavigationPanel()],
    profile: null,
    emptyState: matchingPosts.length === 0 ? toEmptyState('No posts for this tag yet.', 'Back to home', '#') : null,
  };
}

function buildProfilePageModel(routeName: RouteName): PageViewModel {
  const title: string = routeName === 'about' ? `About | ${authorProfile.name}` : `Profile | ${authorProfile.name}`;
  return {
    title,
    description: authorProfile.bio,
    hero: null,
    featuredPosts: [],
    posts: [],
    sidebarPanels: [toNavigationPanel()],
    profile: { profile: authorProfile },
    emptyState: null,
  };
}

function buildNotFoundPageModel(): PageViewModel {
  return {
    title: `Not found | ${authorProfile.name}`,
    description: 'The requested page could not be found.',
    hero: null,
    featuredPosts: [],
    posts: [],
    sidebarPanels: [toNavigationPanel()],
    profile: null,
    emptyState: {
      title: 'Page not found',
      description: 'Try one of the available sections from the navigation.',
      ctaLabel: 'Go home',
      ctaHref: createRouteHref({ name: 'home' }),
    },
  };
}

function toHeroModel(copy: HeroCopy): HeroViewModel {
  return {
    title: copy.title,
    subtitle: copy.subtitle,
    primaryCtaLabel: copy.primaryCtaLabel,
    primaryCtaHref: copy.primaryCtaHref,
    secondaryCtaLabel: copy.secondaryCtaLabel,
    secondaryCtaHref: copy.secondaryCtaHref,
  };
}

function toPostCardModel(post: IndexedPost): PostCardViewModel {
  return {
    slug: post.slug,
    title: post.title,
    summary: post.summary,
    publishedLabel: post.publishedAt,
    readingTimeLabel: `${post.readingTimeMinutes} min read`,
    categoryLabel: post.categoryName,
    href: createRouteHref({ name: 'post', slug: post.slug }),
  };
}

function toNavigationPanel(): SidebarPanelViewModel {
  return { title: 'Navigation', items: navigationEntries.map(toSidebarNavigationItem) };
}

function toCategoryPanel(): SidebarPanelViewModel {
  return { title: 'Categories', items: categories.map((category: Category) => ({ label: category.name, href: createRouteHref({ name: 'category', category: category.slug }), description: category.description })) };
}

function toTagPanel(): SidebarPanelViewModel {
  return { title: 'Tags', items: tags.map((tag: Tag) => ({ label: tag.name, href: createRouteHref({ name: 'tag', tag: tag.slug }) })) };
}

function toArticleSidebarPanel(post: IndexedPost): SidebarPanelViewModel {
  return {
    title: 'Article info',
    items: [
      { label: 'Published', description: post.publishedAt },
      { label: 'Reading time', description: `${post.readingTimeMinutes} minutes` },
      { label: 'Category', href: createRouteHref({ name: 'category', category: post.categorySlug }), description: post.categoryName },
