function toSidebarNavigationItem(entry: NavigationEntry): SidebarItemViewModel {
  return { label: entry.label, href: entry.href };
}

function toEmptyState(description: string, ctaLabel: string, ctaHref: string): EmptyStateViewModel {
  return { title: 'Nothing here yet', description, ctaLabel, ctaHref };
}

function createRouteHref(target: RouteTarget): string {
  return formatRouteHash(target);
}

function findPostBySlug(slug: string | null): IndexedPost | undefined {
  if (slug === null) {
    return undefined;
  }
  return posts.find((post: IndexedPost) => post.slug === slug);
}

function relatedPosts(slug: string): ReadonlyArray<IndexedPost> {
  return posts.filter((post: IndexedPost) => post.slug !== slug).slice(0, 3);
}

function getCategory(slug: string): Category | null {
  return categories.find((category: Category) => category.slug === slug) ?? null;
}

function getTag(slug: string): Tag | null {
  return tags.find((tag: Tag) => tag.slug === slug) ?? null;
}

function renderPageElement(model: PageViewModel): HTMLElement {
  return createElement('main', { className: 'page' },
    renderSectionTitle(model.title, model.description),
    ...(model.hero ? [renderHero(model.hero)] : []),
    ...(model.article ? [renderArticle(model.article)] : []),
    ...(model.featuredPosts.length > 0 ? [renderPostList('Featured posts', model.featuredPosts)] : []),
    ...(model.posts.length > 0 ? [renderPostList('Posts', model.posts)] : []),
    ...(model.profile ? [renderProfile(model.profile)] : []),
    ...(model.sidebarPanels.length > 0 ? [renderSidebar(model.sidebarPanels)] : []),
    ...(model.emptyState ? [renderEmptyState(model.emptyState)] : []),
  );
