}

function renderProfile(profile: ProfileViewModel): HTMLElement {
  return createElement('section', { className: 'profile' }, createElement('h2', {}, profile.profile.name), createElement('p', {}, profile.profile.headline), createElement('p', {}, profile.profile.bio), createElement('p', {}, profile.profile.location));
}

function renderEmptyState(emptyState: EmptyStateViewModel): HTMLElement {
  return createElement('section', { className: 'empty-state' }, createElement('h2', {}, emptyState.title), createElement('p', {}, emptyState.description), createElement('a', { attrs: { href: emptyState.ctaHref } }, emptyState.ctaLabel));
}

import type {
  AuthorProfile,
  BlogPost,
  Category,
  HeroCopy,
  NavigationEntry,
  Tag,
} from './data';
import {
  authorProfile,
  categories,
  heroCopy,
  navigationEntries,
  tags,
} from './data';
import type { RouteName, RouteState, RouteTarget } from './router';
import { formatRouteHash, parseRouteFromHash } from './router';
import {
  clearElement,
  createElement,
  createText,
  type ChildValue,
  type ElementProps,
} from './render';

/** A composed page view model for rendering a route. */
export interface PageViewModel {
  /** Page title. */
  readonly title: string;
  /** Meta description. */
  readonly description: string;
  /** Main hero content. */
  readonly hero?: HeroViewModel | null;
  /** Featured posts to highlight. */
  readonly featuredPosts: ReadonlyArray<PostCardViewModel>;
  /** Primary list of posts. */
  readonly posts: ReadonlyArray<PostCardViewModel>;
  /** Optional detail article. */
  readonly article?: ArticleViewModel | null;
  /** Optional sidebar panels. */
  readonly sidebarPanels: ReadonlyArray<SidebarPanelViewModel>;
  /** Optional profile/about section. */
  readonly profile?: ProfileViewModel | null;
  /** Optional empty state message. */
  readonly emptyState?: EmptyStateViewModel | null;
}

/** Hero section view model. */
export interface HeroViewModel {
  readonly title: string;
  readonly subtitle: string;
  readonly primaryCtaLabel: string;
  readonly primaryCtaHref: string;
  readonly secondaryCtaLabel: string;
  readonly secondaryCtaHref: string;
}

/** Post card view model. */
export interface PostCardViewModel {
  readonly slug: string;
  readonly title: string;
  readonly summary: string;
  readonly publishedLabel: string;
  readonly readingTimeLabel: string;
  readonly categoryLabel: string;
  readonly href: string;
}

/** Article detail view model. */
export interface ArticleViewModel {
  readonly title: string;
  readonly body: string;
  readonly meta: ReadonlyArray<string>;
  readonly href: string;
}

/** Sidebar panel view model. */
export interface SidebarPanelViewModel {
  readonly title: string;
  readonly items: ReadonlyArray<SidebarItemViewModel>;
}

/** Sidebar item view model. */
export interface SidebarItemViewModel {
  readonly label: string;
  readonly href?: string | null;
  readonly description?: string | null;
}

/** Profile/about section view model. */
export interface ProfileViewModel {
  readonly profile: AuthorProfile;
}

/** Empty state view model. */
export interface EmptyStateViewModel {
  readonly title: string;
  readonly description: string;
  readonly ctaLabel: string;
  readonly ctaHref: string;
}

interface IndexedPost extends BlogPost {
  readonly categoryName: string;
}

const posts: ReadonlyArray<IndexedPost> = [];

/** Build a page model from the current route state. */
export function buildPageViewModel(route: RouteState): PageViewModel {
  switch (route.name) {
    case 'home':
      return buildHomePageModel();
    case 'post':
      return buildPostPageModel(route.slug);
    case 'category':
      return buildCategoryPageModel(route.category);
    case 'tag':
      return buildTagPageModel(route.tag);
    case 'about':
    case 'profile':
      return buildProfilePageModel(route.name);
    default:
      return buildNotFoundPageModel();
  }
}

/** Render the current route into the given root element. */
export function renderPage(root: Element, route: RouteState): PageViewModel {
  const viewModel: PageViewModel = buildPageViewModel(route);
  clearElement(root);
  root.appendChild(renderPageElement(viewModel));
  updateDocumentMetadata(viewModel.title, viewModel.description);
  return viewModel;
}

/** Initialize page rendering for hash-based navigation. */
export function initializePages(root: Element): void {
  const renderCurrent = (): void => {
    renderPage(root, parseRouteFromHash(readHash()));
  };
  renderCurrent();
  if (typeof window !== 'undefined') {
    window.addEventListener('hashchange', renderCurrent);
  }
}

function readHash(): string {
  return typeof window === 'undefined' ? '' : window.location.hash;
}

function updateDocumentMetadata(title: string, description: string): void {
  if (typeof document === 'undefined') {
    return;
  }
  document.title = title;
  const existing: HTMLMetaElement | null = document.querySelector('meta[name="description"]');
  const metaDescription: HTMLMetaElement = existing ?? document.head.appendChild(document.createElement('meta'));
  metaDescription.setAttribute('name', 'description');
  metaDescription.setAttribute('content', description);
}

