function buildPostPageModel(slug: string | null): PageViewModel {
  const post: IndexedPost | undefined = findPostBySlug(slug);
  if (post === undefined) {
    return buildNotFoundPageModel();
  }
  const category: Category | null = getCategory(post.categorySlug);
  return {
    title: `${post.title} | ${authorProfile.name}`,
    description: post.summary,
    hero: null,
    featuredPosts: [],
    posts: relatedPosts(post.slug).map(toPostCardModel),
    article: {
      title: post.title,
