import type { PageViewModel } from './pages';
import { buildPageViewModel, renderPage } from './pages';
import type { RouteState } from './router';
import { initializeRouter, onRouteChange, parseRouteFromHash } from './router';
import { clearElement, createElement } from './render';

/** Global app shell state. */
interface AppShellState {
  /** Root application element. */
  readonly root: HTMLElement;
  /** Shell chrome element. */
  readonly shell: HTMLElement;
  /** Main content mount point. */
  readonly content: HTMLElement;
  /** Mobile navigation toggle button. */
  readonly menuToggle: HTMLButtonElement;
  /** Navigation container. */
  readonly navigation: HTMLElement;
  /** Whether the navigation is open on small screens. */
  isMenuOpen: boolean;
  /** Current rendered route. */
  currentRoute: RouteState | null;
  /** Unsubscribe callback for route changes. */
  unsubscribeRouteChanges: (() => void) | null;
  /** Unsubscribe callback for resize changes. */
  unsubscribeViewportChanges: (() => void) | null;
}

let appState: AppShellState | null = null;

/** Initialize the application bootstrap and wire route/render integration. */
export function bootstrapApp(): void {
  if (typeof document === 'undefined') {
    return;
  }

  const root: HTMLElement | null = document.getElementById('root');
  if (root === null) {
    return;
  }

  if (appState !== null) {
    return;
  }

  initializeRouter();

  const shell: HTMLElement = createShell();
  const navigation: HTMLElement | null = shell.querySelector('[data-app-navigation]');
  const content: HTMLElement | null = shell.querySelector('[data-app-content]');
  const menuToggle: HTMLButtonElement | null = shell.querySelector('[data-app-menu-toggle]');

  if (navigation === null || content === null || menuToggle === null) {
    return;
  }

  appState = {
    root,
    shell,
    content,
    menuToggle,
    navigation,
    isMenuOpen: false,
    currentRoute: null,
    unsubscribeRouteChanges: null,
    unsubscribeViewportChanges: null,
  };

  clearElement(root);
  root.appendChild(shell);

  wireShellEvents(appState);
  hydrateInitialRoute(appState);
  subscribeToRouteChanges(appState);
  syncResponsiveState(appState);
}

function createShell(): HTMLElement {
  return createElement('div', {
    className: 'app-shell',
    children: [
      createElement('header', {
        className: 'app-shell__header',
        children: [
          createElement('a', {
            className: 'app-shell__brand',
            attrs: { href: '#' },
            textContent: 'Liu An',
          }),
          createElement('button', {
            className: 'app-shell__menu-toggle',
            attrs: { type: 'button', 'aria-label': 'Toggle navigation', 'data-app-menu-toggle': 'true' },
            textContent: 'Menu',
          }),
          createElement('nav', {
            className: 'app-shell__navigation',
            attrs: { 'data-app-navigation': 'true' },
            children: [
              createElement('a', { attrs: { href: '#' }, textContent: 'Home' }),
              createElement('a', { attrs: { href: '#about' }, textContent: 'About' }),
              createElement('a', { attrs: { href: '#profile' }, textContent: 'Profile' }),
            ],
          }),
        ],
      }),
      createElement('main', {
        className: 'app-shell__content',
        attrs: { 'data-app-content': 'true' },
      }),
    ],
  });
}

function wireShellEvents(state: AppShellState): void {
  state.menuToggle.addEventListener('click', () => {
    setMenuOpen(state, !state.isMenuOpen);
  });

  state.navigation.addEventListener('click', (event: Event) => {
    const target: HTMLElement | null = event.target instanceof HTMLElement ? event.target : null;
    if (target === null) {
      return;
    }

    const anchor: HTMLAnchorElement | null = target.closest('a');
    if (anchor === null) {
      return;
    }

    const href: string | null = anchor.getAttribute('href');
    if (href !== null && href.startsWith('#')) {
      setMenuOpen(state, false);
    }
  });

  state.unsubscribeViewportChanges = subscribeToViewportChanges(state);
}

function hydrateInitialRoute(state: AppShellState): void {
  renderRoute(state, parseRouteFromHash(window.location.hash));
}

function subscribeToRouteChanges(state: AppShellState): void {
  state.unsubscribeRouteChanges = onRouteChange((route: RouteState) => {
    renderRoute(state, route);
  });
}

function subscribeToViewportChanges(state: AppShellState): () => void {
  const handler: () => void = () => syncResponsiveState(state);
  window.addEventListener('resize', handler, { passive: true });
  return () => window.removeEventListener('resize', handler);
}

function renderRoute(state: AppShellState, route: RouteState): void {
  state.currentRoute = route;
  const viewModel: PageViewModel = buildPageViewModel(route);
  renderPage(state.content, viewModel);
  updateNavigationState(state, route);
  syncResponsiveState(state);
}

function updateNavigationState(state: AppShellState, route: RouteState): void {
  const links: NodeListOf<HTMLAnchorElement> = state.navigation.querySelectorAll('a[href]');
  links.forEach((link: HTMLAnchorElement) => {
    const href: string = link.getAttribute('href') ?? '';
    const active: boolean = href === `#${route.hash}` || (href === '#' && route.hash === '');
    link.toggleAttribute('aria-current', active);
  });
}

function setMenuOpen(state: AppShellState, open: boolean): void {
  state.isMenuOpen = open;
  state.navigation.toggleAttribute('data-open', open);
  state.menuToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
}

function syncResponsiveState(state: AppShellState): void {
  const compact: boolean = typeof window !== 'undefined' ? window.innerWidth < 768 : false;
  state.shell.toggleAttribute('data-compact', compact);
  if (!compact) {
    setMenuOpen(state, false);
  }
}

/** Start the app automatically when the DOM is ready. */
export function startApp(): void {
  if (typeof document === 'undefined') {
    return;
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      bootstrapApp();
    }, { once: true });
    return;
  }
  bootstrapApp();
}

startApp();

