import {
  blogPosts,
  categories,
  getAllCategories,
  getAllTags,
  getPostBySlug,
  getPostsByCategory,
  getPostsByTag,
  getRecentPosts,
  tags,
  type BlogPost,
  type Category,
  type Tag,
} from "./data";

/** Minimal test function declaration used to avoid relying on a specific test runner type package. */
declare function describe(name: string, fn: () => void): void;
/** Minimal test function declaration used to avoid relying on a specific test runner type package. */
declare function test(name: string, fn: () => void): void;
/** Minimal expectation function declaration used to avoid relying on a specific test runner type package. */
declare function expect<T>(actual: T): {
  toBe(expected: T): void;
  toEqual(expected: unknown): void;
  toBeUndefined(): void;
  toBeGreaterThan(expected: number): void;
  toBeGreaterThanOrEqual(expected: number): void;
  toBeLessThanOrEqual(expected: number): void;
  toHaveLength(expected: number): void;
  toContain(expected: unknown): void;
};

/** Returns the matching item from a collection by slug. */
function findBySlug<T extends { slug: string }>(items: ReadonlyArray<T>, slug: string): T | undefined {
  return items.find((item: T) => item.slug === slug);
}

/** Creates a set of slugs from a collection. */
function toSlugSet(items: ReadonlyArray<{ slug: string }>): ReadonlySet<string> {
  return new Set<string>(items.map((item: { slug: string }) => item.slug));
}

/** Asserts that a value is truthy. */
function assert(condition: boolean, message: string): void {
  if (!condition) {
    throw new Error(message);
  }
}

/** Verifies that all posts reference valid category and tag records. */
function validateCrossReferences(): void {
  const categorySlugs: ReadonlySet<string> = toSlugSet(categories);
  const tagSlugs: ReadonlySet<string> = toSlugSet(tags);

  for (const post of blogPosts) {
    assert(categorySlugs.has(post.categorySlug), `Unknown category slug referenced by post: ${post.slug}`);
    for (const tagSlug of post.tagSlugs) {
      assert(tagSlugs.has(tagSlug), `Unknown tag slug referenced by post: ${post.slug}`);
    }
  }
}

describe("static blog dataset", () => {
  test("exports remain internally consistent across posts, categories, and tags", () => {
    validateCrossReferences();

    const categoryLookup: ReadonlySet<string> = toSlugSet(categories);
    const tagLookup: ReadonlySet<string> = toSlugSet(tags);

    expect(getAllCategories()).toEqual(categories);
    expect(getAllTags()).toEqual(tags);

    for (const category of categories) {
      const postsInCategory: ReadonlyArray<BlogPost> = getPostsByCategory(category.slug);
      for (const post of postsInCategory) {
        expect(post.categorySlug).toBe(category.slug);
      }
      expect(categoryLookup.has(category.slug)).toBe(true);
    }

    for (const tag of tags) {
      const postsWithTag: ReadonlyArray<BlogPost> = getPostsByTag(tag.slug);
      for (const post of postsWithTag) {
        expect(post.tagSlugs.includes(tag.slug)).toBe(true);
      }
      expect(tagLookup.has(tag.slug)).toBe(true);
    }
  });

  test("slug lookup returns matching posts and undefined for missing records", () => {
    const existingPost: BlogPost | undefined = blogPosts[0];
    assert(existingPost !== undefined, "expected at least one blog post in the dataset");

    expect(getPostBySlug(existingPost.slug)).toBe(existingPost);
    expect(findBySlug(blogPosts, existingPost.slug)).toBe(existingPost);
    expect(getPostBySlug("missing-post-slug")).toBeUndefined();
    expect(getPostBySlug("")).toBeUndefined();
  });

  test("category filtering returns only posts for the requested category and falls back to empty results", () => {
    const category: Category | undefined = categories[0];
    assert(category !== undefined, "expected at least one category in the dataset");

    const categoryPosts: ReadonlyArray<BlogPost> = getPostsByCategory(category.slug);
    expect(categoryPosts.length).toBeGreaterThan(0);
    expect(getPostsByCategory("missing-category")).toEqual([]);
    expect(getPostsByCategory("")).toEqual([]);

    for (const post of categoryPosts) {
      expect(post.categorySlug).toBe(category.slug);
    }
  });

  test("tag filtering returns only posts containing the requested tag and falls back to empty results", () => {
    const tag: Tag | undefined = tags[0];
    assert(tag !== undefined, "expected at least one tag in the dataset");

    const taggedPosts: ReadonlyArray<BlogPost> = getPostsByTag(tag.slug);
    expect(taggedPosts.length).toBeGreaterThan(0);
    expect(getPostsByTag("missing-tag")).toEqual([]);
    expect(getPostsByTag("")).toEqual([]);

    for (const post of taggedPosts) {
      expect(post.tagSlugs.includes(tag.slug)).toBe(true);
    }
  });

  test("recent posts are ordered from newest to oldest and respect limits", () => {
    const recentPosts: ReadonlyArray<BlogPost> = getRecentPosts();
    const allDates: ReadonlyArray<number> = recentPosts.map((post: BlogPost) => new Date(post.publishedAt).getTime());

    expect(recentPosts.length).toBe(Math.min(3, blogPosts.length));
    expect(getRecentPosts(0)).toEqual([]);
    expect(getRecentPosts(-1)).toEqual([]);
    expect(getRecentPosts(blogPosts.length + 10)).toHaveLength(blogPosts.length);

    for (let index: number = 1; index < allDates.length; index += 1) {
      expect(allDates[index]).toBeLessThanOrEqual(allDates[index - 1]);
    }
  });

  test("missing record helpers return empty or undefined fallbacks", () => {
    expect(getPostBySlug("definitely-missing")).toBeUndefined();
    expect(getPostsByCategory("definitely-missing")).toEqual([]);
    expect(getPostsByTag("definitely-missing")).toEqual([]);
  });
});

