import { strict as assert } from "node:assert";
import {
  clearElement,
  createElement,
  createHeroCopySection,
  createHeroSection,
  createNavigation,
  createPostCard,
  createSection,
  createStateView,
  createText,
  escapeHtml,
  mountArticleDetailView,
} from "../../../../proj-1777290684377/sessions/sess-1777290684378/output/render";

function test(name: string, fn: () => void): void {
  try {
    fn();
    console.log(`ok - ${name}`);
  } catch (error: unknown) {
    console.error(`not ok - ${name}`);
    throw error;
  }
}

document.body.innerHTML = "";

test("escapeHtml escapes special characters", () => {
  assert.equal(escapeHtml(`<div class="x">'&'</div>`), "&lt;div class=&quot;x&quot;&gt;&#39;&amp;&#39;&lt;/div&gt;");
});

test("createText converts empty and primitive values", () => {
  assert.equal(createText(42).textContent, "42");
  assert.equal(createText(false).textContent, "false");
  assert.equal(createText(null).textContent, "");
});

test("createElement applies props and appends children", () => {
  const button = createElement(
    "button",
    {
      id: "save",
      className: "btn primary",
      role: "button",
      tabIndex: 2,
      dataset: { track: "hero" },
      attrs: { type: "button", title: "Save & go" },
      textContent: "ignored",
    },
    "Click ",
    createElement("strong", { textContent: "now" }),
  );

  assert.equal(button.id, "save");
  assert.equal(button.className, "btn primary");
  assert.equal(button.getAttribute("role"), "button");
  assert.equal(button.tabIndex, 2);
  assert.equal(button.dataset.track, "hero");
  assert.equal(button.getAttribute("type"), "button");
  assert.equal(button.getAttribute("title"), "Save & go");
  assert.equal(button.textContent, "ignoredClick now");
  assert.equal(button.querySelector("strong")?.textContent, "now");
});

test("createElement keeps text content literal", () => {
  const paragraph = createElement("p", { textContent: "<hero>&'\"" });
  assert.equal(paragraph.textContent, "<hero>&'\"");
  assert.equal(paragraph.innerHTML, "&lt;hero&gt;&amp;&#39;&quot;");
});

test("clearElement removes all child nodes", () => {
  const host = document.createElement("div");
  host.append(createElement("span", { textContent: "a" }), createElement("span", { textContent: "b" }));
  clearElement(host);
  assert.equal(host.childNodes.length, 0);
});

test("createNavigation renders a stable nav structure", () => {
  const nav = createNavigation([
    { label: "Home", href: "/" },
    { label: "Posts", href: "/posts" },
